css:
/* Sapphire Fountains contract styling.

   Every rule is scoped under .contract-doc on purpose: this stylesheet is
   published document-wide by public/js/project_enhancements/contract_viewer.js
   and by the /contract-sign page, and an unscoped rule would restyle the desk
   (or the portal) around the agreement.

   This record is the single source of truth for how a contract looks. The desk
   print, the on-screen viewer, the public signing page and the executed PDF
   emailed after signing all read it — see project_contract._contract_css. */

.contract-doc { font-family: Georgia, 'Times New Roman', serif; font-size: 10.5pt; line-height: 1.45; color: #000; }
.contract-doc p { margin: 5px 0; text-align: justify; }

/* Letterhead: the inline SVG wordmark over a navy rule, first page only. Built
   by project_enhancements/contract_style.py rather than by the templates, so it
   reaches contracts that were signed before it existed. */
.contract-doc .ct-letterhead { text-align: center; margin: 0 0 14px; padding-bottom: 10px; border-bottom: 2px solid #00263E; page-break-after: avoid; }
.contract-doc .ct-letterhead svg { width: 190px; height: auto; }
.contract-doc .ct-letterhead-name { font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif; font-size: 15pt; letter-spacing: 0.08em; color: #00263E; }

/* The document title block, targeted by POSITION rather than by tag. The eight
   shipped templates disagree about tags: <h3> opens the document in six of them
   but is a mid-document section head in the employee-contractor agreement and
   the NDA. So the title is "the <h3> immediately after the letterhead", and its
   subtitle/company/address lines are the run of <p> after that (four is the
   longest run any shipped template has). The chain is inert for the architect
   agreement and the NDA, which open with no title block at all. */
.contract-doc .ct-letterhead + h3 { font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif; font-size: 16pt; text-align: center; letter-spacing: 0.06em; color: #00263E; border: 0; padding: 0; margin: 4px 0 2px; }
.contract-doc .ct-letterhead + h3 + p,
.contract-doc .ct-letterhead + h3 + p + p,
.contract-doc .ct-letterhead + h3 + p + p + p,
.contract-doc .ct-letterhead + h3 + p + p + p + p { text-align: center; font-size: 9.5pt; color: #3b4a56; margin: 1px 0; }

/* Numbered section headings: sans-serif and navy against the serif body. */
.contract-doc h1 { font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif; font-size: 11.5pt; text-transform: uppercase; letter-spacing: 0.04em; color: #00263E; text-align: left; border-left: 3px solid #00263E; padding-left: 8px; margin: 16px 0 7px; page-break-after: avoid; }
.contract-doc h2 { font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif; font-size: 10.5pt; color: #00263E; margin: 12px 0 5px; page-break-after: avoid; }
.contract-doc h3 { font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif; font-size: 11pt; color: #00263E; margin: 12px 0 6px; page-break-after: avoid; }

/* Tables. The templates write label cells as <td><b>Label:</b></td> and never
   use <th>, so tinting the first column is the only way to band them. */
.contract-doc table.ct-table { width: 100%; border-collapse: collapse; margin: 8px 0; page-break-inside: avoid; }
.contract-doc table.ct-table td { border: 1px solid #b9c6d1; padding: 5px 7px; vertical-align: top; font-size: 10pt; }
.contract-doc table.ct-table td:first-child { background: #eef3f7; color: #00263E; }

.contract-doc .ct-blank { display: inline-block; border-bottom: 1px solid #00263E; min-height: 1em; white-space: nowrap; overflow: hidden; }
.contract-doc .ct-cb { font-size: 12pt; color: #00263E; }

/* Signature ink stays black. It is evidence, not decoration. */
.contract-doc .ct-sig { max-height: 60px; vertical-align: bottom; }
.contract-doc .ct-sig-typed { font-family: 'Times New Roman', serif; font-style: italic; font-size: 15pt; color: #000; }
.contract-doc .ct-certificate { margin-top: 24px; padding-top: 10px; border-top: 2px solid #00263E; page-break-inside: avoid; }
.contract-doc .ct-certificate h1 { font-size: 11pt; border: 0; padding: 0; text-align: center; }

/* The running footer is for paper only. frappe.utils.pdf lifts #footer-html out
   of the document and renders it as wkhtmltopdf's --footer-html; in that
   standalone render nothing has a .contract-doc ancestor, so this rule stops
   applying and the footer appears exactly where it should. On every other
   surface the div is still in the body, and hidden. */
.contract-doc #footer-html { display: none; }
